package com.blitterstudio.amiberry.data.model

import android.content.Context
import org.json.JSONArray
import org.json.JSONObject
import java.io.InputStream

/**
 * The shared settings layer's knowledge the launcher needs, as generated
 * from a desktop build into settings_schema.json (assets; regenerated by
 * android/scripts/update_settings_schema.sh and kept fresh by
 * tests/test_settings_schema.sh): the options the launcher writes, the
 * machine presets, how the layer resolves CPU, chipset, memory and sound
 * requests, which options and choices it offers in a state, and what
 * setting a CPU option changes with it. The launcher runs in another
 * process than the emulator, so it reads this data instead of calling the
 * layer or carrying its own copy of the rules.
 */
class SettingsSchema(
	val options: Map<String, Option>,
	val presets: List<Preset>,
	val compatibilityLevels: List<String>,
	/** The ROMs the presets can ask for, by ID. */
	val roms: Map<Int, Rom>,
	/** The CPU and chipset combinations. */
	val resolutions: Resolutions,
	/** Memory sizes against the chipset, the addressing and the JIT. */
	val memoryResolutions: Resolutions,
	/** The sound mode against the cycle-exact modes; null in a schema without it. */
	val soundResolutions: Resolutions? = null,
	/** Which options and choices the layer offers in a state. */
	val availability: Availability = Availability(emptyList()),
	/** What setting a CPU option changes with it; null in a schema without it. */
	val transitions: Transitions? = null,
	/** The built-in AROS Kickstart replacement; null in a schema without it. */
	val aros: Aros? = null,
	/**
	 * What setting a Zorro II fast RAM board's size does, one table per
	 * board: its MB and KB keys are one size, so setting either changes both.
	 */
	val memoryTransitions: List<Transitions> = emptyList()
) {
	/** One ROM a preset needs: the first installed of [ids] ([role] "kick", "ext" or "other"). */
	data class RomRequest(val role: String, val ids: List<Int>)

	data class Rom(val id: Int, val crc32: Long, val role: String, val name: String)

	/**
	 * The built-in AROS Kickstart replacement: the kickstart_rom_file value
	 * that boots it ([romFile], also the end of an RP9's "<file>:AROS") and
	 * the two files it needs in the ROMs directory.
	 */
	data class Aros(val romFile: String, val mainFile: String, val extFile: String)

	/**
	 * The Quick Start models: every preset with a configuration the Android
	 * build has, except the arcade boards. Their configuration is the first
	 * installed game, which also sets hardware (most ALG games are NTSC); the
	 * schema cannot describe it, and the launcher's configuration would
	 * override it. Configurations that need a feature the Android build
	 * leaves out come after the others (tests/test_settings_schema.sh), so
	 * dropping them keeps the others' indices the emulator's.
	 */
	val models: List<AmigaModel> by lazy {
		presets
			.filter { !it.arcade }
			.map { preset -> preset to preset.configs.filter { config -> config.requires.all { it in ANDROID_FEATURES } } }
			.filter { (_, configs) -> configs.isNotEmpty() }
			.map { (preset, configs) -> AmigaModel(preset.id, preset.label, configs, preset.compatibilityMax) }
	}

	data class Choice(val value: String, val label: String)

	/**
	 * One option of the settings layer, as people should see it: the
	 * layer's [label] and [help] (shown under the control), the [constraint]
	 * saying why it may be unavailable, and for numbers how the stored value
	 * reads ([reversed], [scale], [unit]; [level] for a number set by feel,
	 * shown as a slider). Stored values keep their .uae spelling throughout.
	 * [androidDefault] is the Android build's default where it differs from
	 * [default] (the schema comes from a desktop build). [group] is the
	 * layer's group the Settings tabs place it by; [presetOnly] marks an
	 * option the schema describes only because a preset sets it, which the
	 * launcher writes but does not show.
	 */
	data class Option(
		val id: String,
		val type: String,
		val apply: String,
		val default: String,
		val min: Double?,
		val max: Double?,
		val choices: List<Choice>,
		val label: String = id,
		val help: String = "",
		val constraint: String? = null,
		val step: Double? = null,
		val unit: String? = null,
		val scale: Double = 1.0,
		val reversed: Boolean = false,
		val androidDefault: String? = null,
		val group: String = "",
		val level: Boolean = false,
		val presetOnly: Boolean = false
	) {
		/** The default the Android emulator gives the option. */
		val defaultOnAndroid: String
			get() = androidDefault ?: default

		/** The layer's label of a choice value; null when [value] is not one of [choices]. */
		fun choiceLabel(value: String): String? = choices.firstOrNull { it.value == value }?.label

		/**
		 * The number a person sees for a stored one: a reversed option's
		 * range turned around (attenuation 0 reads as 100% volume), then
		 * divided by the scale.
		 */
		fun shown(stored: Double): Double {
			var number = stored
			if (reversed && min != null && max != null) number = min + max - number
			return number / scale
		}

		/**
		 * The stored number for a shown one: [shown] undone, rounded to the
		 * step counted from the bottom of the range and, for an integer, to
		 * a whole number.
		 */
		fun stored(shown: Double): Double {
			var number = shown * scale
			if (reversed && min != null && max != null) number = min + max - number
			val step = step
			if (step != null && step > 0) {
				val origin = min ?: 0.0
				number = origin + Math.round((number - origin) / step) * step
			}
			return if (type == TYPE_INT) Math.round(number).toDouble() else number
		}

		/** The range of stored numbers as the numbers shown (low to high). */
		val shownRange: ClosedFloatingPointRange<Double>?
			get() {
				val low = min ?: return null
				val high = max ?: return null
				val a = shown(low)
				val b = shown(high)
				return minOf(a, b)..maxOf(a, b)
			}

		/** The step of the shown number: the option's step (1 for none) over the scale. */
		val shownStep: Double
			get() = maxOf((step?.takeIf { it > 0 } ?: 1.0) / scale, 0.0001)

		/** A shown number as text, to the decimals of the shown step ("12.5" for a step of 0.1). */
		fun shownText(shown: Double): String {
			val free = type == TYPE_REAL && (step ?: 0.0) <= 0
			return plainNumber(shown, if (free) null else decimalsOf(shownStep))
		}

		/** A number with the unit after it: "80%", "720 px", "4096 KB". */
		fun withUnit(text: String): String {
			val unit = unit?.takeIf { it.isNotEmpty() } ?: return text
			return if (unit == "%") text + unit else "$text $unit"
		}

		/** A stored number as it reads with its unit ("80%" for attenuation 20); other text as it is. */
		fun numberText(stored: String): String =
			stored.toDoubleOrNull()?.let { withUnit(shownText(shown(it))) } ?: stored

		/**
		 * Whether the option is an on/off switch stored as "1" and "0": an
		 * integer from 0 to 1, or exactly two choices "0" then "1" whose
		 * first is named as off ("Disabled", "Off", "No", "None").
		 */
		val isSwitch: Boolean
			get() = when (type) {
				TYPE_INT -> min == 0.0 && max == 1.0
				TYPE_CHOICE -> choices.map { it.value } == listOf("0", "1") &&
					choices[0].label.lowercase() in OFF_LABELS
				else -> false
			}

		/**
		 * Whether [value] shows as a switch: the option is one ([isSwitch], or
		 * a bool) and the value is one of its two states. Any other stored
		 * value (a hand-edited threshold) keeps the option's own control.
		 */
		fun showsAsSwitch(value: String): Boolean = when {
			type == TYPE_BOOL -> value == "true" || value == "false"
			isSwitch -> value == "0" || value == "1"
			else -> false
		}

		/**
		 * A stored value as the controls show it: [on] or [off] for a switch
		 * or bool, a choice's label, a number in its unit; other text as it is.
		 */
		fun valueText(value: String, on: String, off: String): String = when {
			type == TYPE_BOOL && (value == "true" || value == "false") -> if (value == "true") on else off
			showsAsSwitch(value) -> if (value == "1") on else off
			type == TYPE_CHOICE -> choiceLabel(value) ?: value
			type == TYPE_INT || type == TYPE_REAL -> numberText(value)
			else -> value
		}
	}

	/** The option [id] describes; null when the schema does not list it. */
	fun option(id: String): Option? = options[id]

	/** The layer's label of [id]; null when the schema does not list it. */
	fun label(id: String): String? = options[id]?.label

	/** The Android emulator's default of every option, by ID: the values a state has where nothing sets them. */
	val defaults: Map<String, String> by lazy { options.mapValues { it.value.defaultOnAndroid } }

	/** Why [id] may be unavailable, as the layer words it; null when it always is. */
	fun constraint(id: String): String? = options[id]?.constraint?.takeIf { it.isNotBlank() }

	/** The layer's label of the choice [value] of [id]; null when it is not one. */
	fun choiceLabel(id: String, value: String): String? = options[id]?.choiceLabel(value)

	/**
	 * One configuration of a preset. [levels] is the machine at each
	 * compatibility level (0 the best compatibility, up to the preset's
	 * compatibilityMax): every option whose value differs from a fresh
	 * configuration's, .uae spelling, so a configuration file of these values
	 * loads as the machine (paths left out). [romSets] are the ways it can be
	 * built: one ROM from each request of a set (the emulator prefers earlier
	 * sets). [requires] names emulator features it needs that a build may
	 * leave out ("ppc" for the PowerPC boards).
	 */
	data class PresetConfig(
		val label: String,
		val levels: List<Map<String, String>>,
		val romSets: List<List<RomRequest>>,
		val requires: List<String> = emptyList()
	)

	/** A machine preset; [arcade] for the arcade boards, whose configuration is the first installed game. */
	data class Preset(
		val id: String,
		val label: String,
		val compatibilityMax: Int,
		val configs: List<PresetConfig>,
		val arcade: Boolean = false
	)

	companion object {
		const val ASSET = "settings_schema.json"

		/**
		 * The features a preset configuration can require that the Android
		 * build has: none so far, it has no PowerPC boards (CMakeLists.txt
		 * turns USE_PPC off for Android).
		 */
		private val ANDROID_FEATURES = emptySet<String>()

		const val TYPE_BOOL = "bool"
		const val TYPE_INT = "int"
		const val TYPE_REAL = "real"
		const val TYPE_CHOICE = "choice"

		/** The labels that make a first choice of "0" read as off (see [Option.isSwitch]). */
		private val OFF_LABELS = setOf("disabled", "off", "no", "none")

		/** The decimals a step needs: 0 for 1, 1 for 0.5, 2 for 0.01. */
		internal fun decimalsOf(step: Double): Int {
			var digits = 0
			var value = kotlin.math.abs(step)
			while (digits < 6 && kotlin.math.abs(value - Math.rint(value)) > 1e-9) {
				value *= 10
				digits++
			}
			return digits
		}

		/** [number] without trailing zeros, rounded to [decimals] when given. */
		internal fun plainNumber(number: Double, decimals: Int?): String {
			var value = java.math.BigDecimal.valueOf(number)
			if (decimals != null) value = value.setScale(decimals, java.math.RoundingMode.HALF_UP)
			value = value.stripTrailingZeros()
			if (value.signum() == 0) return "0"
			return value.toPlainString()
		}

		@Volatile
		private var loaded: SettingsSchema? = null

		/** The bundled schema, read once per process; null when it cannot be read. */
		fun bundled(context: Context): SettingsSchema? =
			loaded ?: synchronized(this) {
				loaded ?: runCatching {
					context.applicationContext.assets.open(ASSET).use { parse(it) }
				}.getOrNull()?.also { loaded = it }
			}

		/**
		 * The schema [bundled] read, if any (for code without a Context). The
		 * JVM unit tests have no assets; Gradle names the source file in the
		 * amiberry.settingsSchema system property instead.
		 */
		val current: SettingsSchema?
			get() = loaded ?: System.getProperty("amiberry.settingsSchema")?.let { path ->
				synchronized(this) {
					loaded ?: java.io.File(path).inputStream().use { parse(it) }.also { loaded = it }
				}
			}

		/** Makes [schema] the one [current] returns (tests). */
		fun install(schema: SettingsSchema?) {
			loaded = schema
		}

		fun parse(input: InputStream): SettingsSchema =
			parse(JSONObject(input.bufferedReader(Charsets.UTF_8).readText()))

		fun parse(json: JSONObject): SettingsSchema {
			val options = LinkedHashMap<String, Option>()
			val optionArray = json.getJSONArray("options")
			for (i in 0 until optionArray.length()) {
				val o = optionArray.getJSONObject(i)
				// A choice that needs a feature the Android build leaves out
				// (the genlock's video sources need VIDEOGRAB) is not offered.
				val choices = o.optJSONArray("choices")?.let { array ->
					List(array.length()) { array.getJSONObject(it) }
						.filter { choice -> choice.optJSONArray("requires")?.toStringList().orEmpty().all { it in ANDROID_FEATURES } }
						.map { choice -> Choice(choice.getString("value"), choice.getString("label")) }
				} ?: emptyList()
				fun text(key: String): String? = if (o.has(key) && !o.isNull(key)) o.getString(key) else null
				fun number(key: String): Double? = if (o.has(key) && !o.isNull(key)) o.getDouble(key) else null
				val id = o.getString("id")
				val option = Option(
					id = id,
					type = o.getString("type"),
					apply = o.getString("apply"),
					default = o.getString("default"),
					min = number("min"),
					max = number("max"),
					choices = choices,
					label = text("label")?.takeIf { it.isNotBlank() } ?: id,
					help = text("help").orEmpty(),
					constraint = text("constraint")?.takeIf { it.isNotBlank() },
					step = number("step"),
					unit = text("unit")?.takeIf { it.isNotBlank() },
					scale = number("scale")?.takeIf { it != 0.0 } ?: 1.0,
					reversed = o.optBoolean("reversed", false),
					androidDefault = text("android_default"),
					group = text("group").orEmpty(),
					level = o.optBoolean("level", false),
					presetOnly = o.optBoolean("preset_only", false)
				)
				options[option.id] = option
			}

			val presetArray = json.getJSONArray("presets")
			val presets = List(presetArray.length()) { i ->
				val p = presetArray.getJSONObject(i)
				val configArray = p.getJSONArray("configs")
				Preset(
					id = p.getString("id"),
					label = p.getString("label"),
					compatibilityMax = p.getInt("compatibility_max"),
					arcade = p.optBoolean("arcade", false),
					configs = List(configArray.length()) { c ->
						val config = configArray.getJSONObject(c)
						val setArray = config.getJSONArray("rom_sets")
						val romSets = List(setArray.length()) { set ->
							val requests = setArray.getJSONArray(set)
							List(requests.length()) { r ->
								val rom = requests.getJSONObject(r)
								val ids = rom.getJSONArray("ids")
								RomRequest(rom.getString("role"), List(ids.length()) { ids.getInt(it) })
							}
						}
						val levelArray = config.getJSONArray("levels")
						PresetConfig(
							config.getString("label"),
							List(levelArray.length()) { levelArray.getJSONObject(it).toStringMap() },
							romSets,
							config.optJSONArray("requires")?.toStringList().orEmpty()
						)
					}
				)
			}

			val levels = json.getJSONArray("compatibility_levels").toStringList()
			val romArray = json.getJSONArray("roms")
			val roms = LinkedHashMap<Int, Rom>()
			for (i in 0 until romArray.length()) {
				val r = romArray.getJSONObject(i)
				val rom = Rom(r.getInt("id"), r.getString("crc32").toLong(16), r.getString("role"), r.getString("name"))
				roms[rom.id] = rom
			}
			val resolutions = Resolutions.parse(json.getJSONObject("resolutions"))
			val memoryResolutions = Resolutions.parse(json.getJSONObject("memory_resolutions"))
			val soundResolutions = json.optJSONObject("sound_resolutions")?.let { Resolutions.parse(it) }
			val availability = Availability.parse(json.optJSONArray("availability") ?: JSONArray())
			val transitions = json.optJSONObject("transitions")?.let { Transitions.parse(it) }
			val aros = json.optJSONObject("aros")?.let {
				Aros(it.getString("rom_file"), it.getString("main_file"), it.getString("ext_file"))
			}
			val memoryTransitions = json.optJSONArray("memory_transitions")?.let { array ->
				List(array.length()) { Transitions.parse(array.getJSONObject(it)) }
			}.orEmpty()
			return SettingsSchema(
				options, presets, levels, roms, resolutions, memoryResolutions,
				soundResolutions, availability, transitions, aros, memoryTransitions
			)
		}

		private fun JSONObject.toStringMap(): Map<String, String> {
			val map = LinkedHashMap<String, String>()
			for (key in keys()) map[key] = getString(key)
			return map
		}

		private fun JSONArray.toStringList(): List<String> = List(length()) { getString(it) }
	}
}

/**
 * What the emulator runs with when a configuration names a combination of
 * values: for each combination of [inputs], the values the core's checks
 * leave after a configuration load. The [free] options are not part of the
 * combination; for each the table says what each of its values resolves to,
 * so a value the checks do not force is kept.
 */
class Resolutions private constructor(
	val inputs: List<String>,
	val free: Map<String, List<String>>,
	private val rows: Map<List<String>, Row>
) {
	private class Row(val resolved: List<String>, val free: List<List<String>>)

	/**
	 * The resolved inputs, and the free options in [request] resolved from
	 * their own values; null when the table has no such combination.
	 */
	fun resolve(request: Map<String, String>): Map<String, String>? {
		val key = inputs.map { request[it] ?: return null }
		val row = rows[key] ?: return null
		val result = LinkedHashMap<String, String>()
		inputs.forEachIndexed { i, id -> result[id] = row.resolved[i] }
		free.keys.forEachIndexed { f, id ->
			val value = request[id] ?: return@forEachIndexed
			val index = free.getValue(id).indexOf(value)
			if (index >= 0) result[id] = row.free[f][index]
		}
		return result
	}

	companion object {
		fun parse(json: JSONObject): Resolutions {
			fun JSONArray.strings() = List(length()) { getString(it) }
			val inputs = json.getJSONArray("inputs").strings()
			val freeArray = json.getJSONArray("free")
			val free = LinkedHashMap<String, List<String>>()
			for (i in 0 until freeArray.length()) {
				val f = freeArray.getJSONObject(i)
				free[f.getString("id")] = f.getJSONArray("values").strings()
			}
			val rowArray = json.getJSONArray("rows")
			val rows = HashMap<List<String>, Row>(rowArray.length() * 2)
			for (i in 0 until rowArray.length()) {
				val row = rowArray.getJSONArray(i)
				val freeValues = row.getJSONArray(2).let { a -> List(a.length()) { a.getJSONArray(it).strings() } }
				rows[row.getJSONArray(0).strings()] = Row(row.getJSONArray(1).strings(), freeValues)
			}
			return Resolutions(inputs, free, rows)
		}
	}
}

/**
 * The states a table of the layer's answers lists, one row each: every
 * combination of the [inputs]' values (option ID to its values, .uae
 * spelling), the last input changing fastest.
 */
class StateSpace(val inputs: List<Pair<String, List<String>>>) {
	/** The row of [state] (values by option ID); null when it lacks an input or names a value the table does not list. */
	fun row(state: Map<String, String>): Int? {
		var row = 0
		for ((id, values) in inputs) {
			val index = values.indexOf(state[id] ?: return null)
			if (index < 0) return null
			row = row * values.size + index
		}
		return row
	}

	companion object {
		fun parse(inputs: JSONArray): StateSpace = StateSpace(parseFields(inputs))

		/** [{"id": ..., "values": [...]}, ...] as pairs. */
		internal fun parseFields(array: JSONArray): List<Pair<String, List<String>>> = List(array.length()) { i ->
			val field = array.getJSONObject(i)
			val values = field.getJSONArray("values")
			field.getString("id") to List(values.length()) { values.getString(it) }
		}
	}
}

/**
 * Which options and choices the settings layer offers in a state (its
 * is_available and choice_is_available answers), from tables the schema
 * export makes by asking the layer in every state of the tables' inputs.
 */
class Availability(private val tables: List<Table>) {
	/**
	 * One table: per state, a mask of the [options] that are available
	 * (bit i for options[i]), then one mask per [choices] option of the
	 * choices that are (bit j for its j-th value).
	 */
	class Table(
		val space: StateSpace,
		val options: List<String>,
		val choices: List<Pair<String, List<String>>>,
		private val rows: List<LongArray>
	) {
		fun isAvailable(id: String, state: Map<String, String>): Boolean? {
			val bit = options.indexOf(id).takeIf { it >= 0 } ?: return null
			val row = space.row(state) ?: return null
			return rows[row][0] and (1L shl bit) != 0L
		}

		fun choices(id: String, state: Map<String, String>): List<String>? {
			val index = choices.indexOfFirst { it.first == id }.takeIf { it >= 0 } ?: return null
			val row = space.row(state) ?: return null
			val mask = rows[row][1 + index]
			return choices[index].second.filterIndexed { bit, _ -> mask and (1L shl bit) != 0L }
		}
	}

	/** Whether the layer offers [id] in [state] (.uae values by option ID); null when no table answers. */
	fun isAvailable(id: String, state: Map<String, String>): Boolean? =
		tables.firstNotNullOfOrNull { it.isAvailable(id, state) }

	/** The choices of [id] the layer offers in [state], in the option's order; null when no table answers. */
	fun choices(id: String, state: Map<String, String>): List<String>? =
		tables.firstNotNullOfOrNull { it.choices(id, state) }

	companion object {
		fun parse(array: JSONArray): Availability = Availability(List(array.length()) { t ->
			val table = array.getJSONObject(t)
			val options = table.getJSONArray("options")
			val rowArray = table.getJSONArray("rows")
			Table(
				StateSpace.parse(table.getJSONArray("inputs")),
				List(options.length()) { options.getString(it) },
				StateSpace.parseFields(table.getJSONArray("choices")),
				List(rowArray.length()) { r ->
					val row = rowArray.getJSONArray(r)
					LongArray(row.length()) { row.getLong(it) }
				}
			)
		})
	}
}

/**
 * What setting an option does in each state, as the settings layer's
 * setters do it (a 68000 drops the JIT, cycle-exact turns immediate blits
 * off): recorded by the schema export, which sets each of the [actions]'
 * values in every state and reads the [fields] back.
 */
class Transitions private constructor(
	val space: StateSpace,
	val fields: List<String>,
	val actions: List<Pair<String, List<String>>>,
	private val outcomes: List<Map<String, String>>,
	private val rows: List<IntArray>
) {
	/**
	 * Setting an option in a state: [refused] when the layer does not take
	 * the value there, else the fields it [writes] (.uae values by option
	 * ID): inputs it changes and other fields it forces to one value.
	 */
	data class Transition(val refused: Boolean, val writes: Map<String, String>)

	/** Setting [id] to [value] in [state]; null when the table does not have it. */
	fun of(state: Map<String, String>, id: String, value: String): Transition? {
		var column = 0
		for ((action, values) in actions) {
			if (action == id) {
				val index = values.indexOf(value).takeIf { it >= 0 } ?: return null
				column += index
				val row = space.row(state) ?: return null
				val outcome = rows[row][column]
				return if (outcome < 0) Transition(true, emptyMap()) else Transition(false, outcomes[outcome])
			}
			column += values.size
		}
		return null
	}

	companion object {
		fun parse(json: JSONObject): Transitions {
			val fieldArray = json.getJSONArray("fields")
			val fields = List(fieldArray.length()) { fieldArray.getString(it) }
			val outcomeArray = json.getJSONArray("outcomes")
			val outcomes = List(outcomeArray.length()) { o ->
				val writes = outcomeArray.getJSONArray(o)
				val map = LinkedHashMap<String, String>()
				for (i in 0 until writes.length() step 2) map[fields[writes.getInt(i)]] = writes.getString(i + 1)
				map
			}
			val rowArray = json.getJSONArray("rows")
			return Transitions(
				StateSpace.parse(json.getJSONArray("inputs")),
				fields,
				StateSpace.parseFields(json.getJSONArray("actions")),
				outcomes,
				List(rowArray.length()) { r ->
					val row = rowArray.getJSONArray(r)
					IntArray(row.length()) { row.getInt(it) }
				}
			)
		}
	}
}
